const data = $input.first().json;

const cbsList = (data.cbsAccountsCreated && data.cbsAccountsCreated.length > 0)
  ? data.cbsAccountsCreated.join(', ')
  : 'N/A';

const message = `
✅ *BEYOND LO AUTOMATION - EXECUTION SUCCESS*
--------------------------------------------------
• *Feature*: ${data.feature}
• *Environment*: ${data.environment.toUpperCase()}
• *Scenarios Passed*: ${data.metrics.passed} / ${data.metrics.totalScenarios} (100%)
• *Duration*: ${data.durationSeconds}s
• *CBS Accounts Generated*: ${cbsList}
• *Triggered By*: ${data.triggeredBy}

📊 *Full Excel Report*: http://localhost:5050${data.reports.excelDownloadUrl}
`;

return { json: { success: true, message, raw: data } };

const data = $input.first().json;
const triage = data.aiTriage || {};

const message = `
🚨 *BEYOND LO AUTOMATION - TEST FAILURE ALERT*
--------------------------------------------------
• *Feature*: ${data.feature}
• *Environment*: ${data.environment.toUpperCase()}
• *Failed Scenarios*: ${data.metrics.failed} / ${data.metrics.totalScenarios}
• *Pass Rate*: ${data.metrics.passRate}
• *Duration*: ${data.durationSeconds}s

🤖 *AI ROOT-CAUSE TRIAGE*:
• *Category*: ${triage.failureCategory || 'UNKNOWN'}
• *Severity*: ${triage.severity || 'HIGH'}
• *Summary*: ${triage.rootCauseSummary || 'Assertion failed.'}
• *Failing Service*: ${triage.failingEndpoint || 'Check logs'}
• *Recommended Action*: ${triage.recommendedAction || 'Inspect stack trace'}

📊 *Full Excel Report*: http://localhost:5050${data.reports.excelDownloadUrl}
`;

return {
  json: {
    success: false,
    message,
    isRealBug: triage.failureCategory === 'CODE_REGRESSION',
    triage,
    raw: data
  }
};

const mantis = $input.first().json;
const prev = $node['Format AI Failure Triage'].json;

const mantisMsg = `
🐞 *MANTISBT DEFECT TICKET AUTOMATICALLY CREATED*
--------------------------------------------------
• *Ticket ID*: #${mantis.issue ? mantis.issue.formattedId : 'N/A'}
• *Summary*: ${mantis.issue ? mantis.issue.summary : 'Defect logged'}
• *Project*: ${mantis.issue ? mantis.issue.project : 'BeyondLO'}
• *URL*: ${mantis.issue ? mantis.issue.url : 'http://localhost:5050'}
• *Mode*: ${mantis.simulated ? 'SIMULATED (Pending Mantis URL/Token)' : 'LIVE'}

${prev.message}
`;

return { json: { success: false, mantisAlert: mantisMsg, mantisResult: mantis } };
